const specialTypes=['rapid','shotgun','sniper','rail','rocket'],slotColors=[0x56dfff,0xffac52],ammoPickupAmounts={rapid:80,shotgun:8,sniper:4,rail:5,rocket:1};let selectedWeapons=[],slotAmmo=[0,0],equippedSlot=0,loadoutConfirmed=false;const weaponImages={};
const weaponInfo={rapid:{description:'압도적인 연사와 강한 반동. 탄약을 빠르게 소모합니다.',damage:'65 / 발'},shotgun:{description:'9발의 산탄을 동시에 발사. 가까울수록 강력합니다.',damage:'30 × 9 · 최대 270'},sniper:{description:'우클릭 4배율 스코프. 헤드샷 3배로 약점을 정확히 저격합니다.',damage:'220 · 헤드샷 660'},rail:{description:'버튼을 누르고 충전. 큰 보라색 탄환으로 광역 공격합니다.',damage:'188~800 · 충전 비례'},rocket:{description:'우클릭으로 1초 락온. 한 발의 미사일이 적을 추적해 대폭발합니다.',damage:'1,800 · 반경 10m'}};
function renderLoadout(){for(const type of specialTypes){const index=selectedWeapons.indexOf(type),button=$('loadout-'+type),info=weaponInfo[type];button.setAttribute?.('aria-pressed',String(index>=0));button.innerHTML=`<div class="weaponPicture">${weaponImages[type]?`<img src="${weaponImages[type]}" alt="${weapons[type].name} 모델">`:''}<span>${index>=0?`${index+2}번 선택`:'선택'}</span></div><h3>${weapons[type].name}</h3><p>${info.description}</p><dl><div><dt>기본 피해</dt><dd>${info.damage}</dd></div><div><dt>최대 탄약</dt><dd>${weapons[type].ammo}발</dd></div><div><dt>탄약팩 보급</dt><dd>+${ammoPickupAmounts[type]}발</dd></div></dl>`;} $('loadoutSelection').textContent=selectedWeapons.length?selectedWeapons.map((type,i)=>`${i+2}번: ${weapons[type].name} · ${i===0?'하늘색':'주황색'} 탄약`).join(' / '):'첫 번째 선택은 2번, 두 번째 선택은 3번 슬롯';$('confirmLoadout').disabled=selectedWeapons.length!==2;$('confirmLoadout').textContent=selectedWeapons.length===2?'전투 시작 →':`무기 ${2-selectedWeapons.length}개를 더 선택해주세요`;}
function makeWeaponImages(){if(weaponImages.rapid)return;const preview=new THREE.WebGLRenderer({alpha:true,antialias:true,preserveDrawingBuffer:true});if(!preview.domElement?.toDataURL)return;preview.setSize(480,240);preview.setPixelRatio(1);const world=new THREE.Scene(),eye=new THREE.PerspectiveCamera(34,2,.01,20);world.add(new THREE.HemisphereLight(0xd9f2ff,0x35434e,3));const light=new THREE.DirectionalLight(0xffffff,4);light.position.set(2,4,3);world.add(light);for(const type of specialTypes){const model=createWeaponModel(type);world.add(model);const bounds=new THREE.Box3().setFromObject(model),center=bounds.getCenter(new THREE.Vector3()),size=bounds.getSize(new THREE.Vector3());eye.position.copy(center).add(new THREE.Vector3(1,.55,.55).normalize().multiplyScalar(Math.max(size.z,size.x,size.y)*1.5));eye.lookAt(center);preview.render(world,eye);weaponImages[type]=preview.domElement.toDataURL('image/png');world.remove(model);clearItem(model);}preview.dispose();}
function openLoadout(){makeWeaponImages();renderLoadout();$('overlay').style.display='none';$('loadoutOverlay').hidden=false;$('loadout-rapid').focus?.();}

function chooseLoadout(type){const index=selectedWeapons.indexOf(type);if(index>=0)selectedWeapons.splice(index,1);else if(selectedWeapons.length<2)selectedWeapons.push(type);renderLoadout();}
function syncAmmo(){if(equippedSlot>0&&selectedWeapons[equippedSlot-1]===weapon)slotAmmo[equippedSlot-1]=Math.max(0,ammo);}
function equipSlot(slot){if(slot>0&&!selectedWeapons[slot-1])return;syncAmmo();equippedSlot=slot;weapon=slot===0?'pistol':selectedWeapons[slot-1];ammo=slot===0?Infinity:slotAmmo[slot-1];chargeHeld=false;photonCharge=0;lockTarget=null;lockTime=0;firing=false;rightDrag=false;adsBlend=0;recoil=0;shotgunKick=0;$('scope').style.opacity=0;$('rocketLock').style.opacity=0;updateCombatRing();updateSlotHUD();}
function updateSlotHUD(){syncAmmo();const html=[`<span class="${equippedSlot===0?'equipped':''}"><b>1 · 기관총</b>∞</span>`,...selectedWeapons.map((type,i)=>`<span style="color:#${slotColors[i].toString(16)}" class="${equippedSlot===i+1?'equipped':''} ${slotAmmo[i]===0?'empty':''}"><b>${i+2} · ${weapons[type].name}</b>${slotAmmo[i]} / ${weapons[type].ammo}</span>`)].join('');if($('weaponSlots').innerHTML!==html)$('weaponSlots').innerHTML=html;}
const pickupMessages=[];let pickupFlashTime=0;
function supplyFeedback(d,amount){const color=d.kind==='health'?'#83ff94':'#'+slotColors[d.slot].toString(16),el=document.createElement('div');el.className='pickupMessage';el.style.color=color;el.textContent=d.kind==='health'?`HP +${amount}`:`${d.slot+2}번 탄약 +${amount}`;$('pickupNumbers').appendChild?.(el);pickupMessages.push({el,life:.85});pickupFlashTime=.35;$('pickupFlash').style.background=`radial-gradient(ellipse at center,transparent 38%,${color}66 100%)`;playSound('ammo-pickup',.5,d.kind==='health'?.85:1);if(d.m)burst(d.m.position,parseInt(color.slice(1),16),12);}
function updateSupplyFeedback(dt){pickupFlashTime=Math.max(0,pickupFlashTime-dt);$('pickupFlash').style.opacity=pickupFlashTime/.35;for(let i=pickupMessages.length-1;i>=0;i--){pickupMessages[i].life-=dt;if(pickupMessages[i].life<=0){pickupMessages[i].el.remove();pickupMessages.splice(i,1);}}}
function pickupSupply(d){if(d.kind==='health'){if(player.hp>=maxPlayerHP())return false;const healed=Math.min(30,maxPlayerHP()-player.hp);player.hp+=healed;supplyFeedback(d,healed);notify('HP팩 · 체력 +30');}else{const type=selectedWeapons[d.slot];if(!type)return false;syncAmmo();const before=slotAmmo[d.slot];slotAmmo[d.slot]=Math.min(weapons[type].ammo,before+ammoPickupAmounts[type]);if(slotAmmo[d.slot]===before)return false;if(equippedSlot===d.slot+1)ammo=slotAmmo[d.slot];supplyFeedback(d,slotAmmo[d.slot]-before);notify(`${d.slot+2}번 ${weapons[type].name} · 탄약 +${slotAmmo[d.slot]-before}`);}updateSlotHUD();updateCombatRing();return true;}
const soundBuffers=new Map();let soundLoading=null,soundVoices=0,explosionShake=0;
const soundFiles=['ammo-pickup','melee-impact','headshot-clang','laserSmall_000','laserSmall_001','laserSmall_002','laserLarge_000','laserLarge_001','laserLarge_002','explosionCrunch_000','explosionCrunch_001','lowFrequency_explosion_000','forceField_000','doorOpen_000','computerNoise_000','firearms/rifle','firearms/automatic','firearms/shotgun','firearms/sniper','firearms/rifle_alt','firearms/automatic_alt','firearms/shotgun_alt','firearms/sniper_alt'];
function loadSounds(){if(soundLoading)return soundLoading;soundLoading=Promise.all(soundFiles.map(async name=>{try{const response=await fetch(new URL('audio/'+(['headshot-clang','melee-impact','ammo-pickup'].includes(name)?name+'.wav':(name.startsWith('firearms/')?name:'kenney/'+name)+'.ogg'),document.baseURI));if(!response.ok)throw new Error(response.status);const buffer=await audio.decodeAudioData(await response.arrayBuffer());soundBuffers.set(name,buffer);}catch(error){console.warn('Sound unavailable',name,error);}}));return soundLoading;}
function updateAudioListener(){if(!audio)return;const l=audio.listener,forward=new THREE.Vector3(-Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch));if(l.positionX){l.positionX.value=player.pos.x;l.positionY.value=player.pos.y;l.positionZ.value=player.pos.z;l.forwardX.value=forward.x;l.forwardY.value=forward.y;l.forwardZ.value=forward.z;l.upX.value=0;l.upY.value=1;l.upZ.value=0;}else{l.setPosition(player.pos.x,player.pos.y,player.pos.z);l.setOrientation(forward.x,forward.y,forward.z,0,1,0);}}
function playSound(name,volume=.2,rate=1,pos=null){if(!audio||soundVoices>=24)return;const buffer=soundBuffers.get(name);if(!buffer)return;updateAudioListener();const source=audio.createBufferSource(),gain=audio.createGain();source.buffer=buffer;source.playbackRate.value=rate;gain.gain.value=volume;let panner=null,filter=null;if(pos){panner=audio.createPanner();panner.panningModel='HRTF';panner.distanceModel='inverse';panner.refDistance=4;panner.maxDistance=100;panner.rolloffFactor=1.25;panner.setPosition(pos.x,pos.y,pos.z);filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=18000/(1+pos.distanceTo(player.pos)/18);source.connect(filter);filter.connect(panner);panner.connect(gain);}else source.connect(gain);gain.connect(audio.destination);soundVoices++;source.onended=()=>{soundVoices--;source.disconnect();filter?.disconnect();panner?.disconnect();gain.disconnect();};source.start();}

function tone(freq,duration=.07,type='triangle',vol=.08,pos=null){playSound(freq<160?'lowFrequency_explosion_000':freq>=900?'forceField_000':freq>=500?'doorOpen_000':'laserSmall_002',Math.min(.22,vol*1.5),Math.max(.6,Math.min(1.8,freq/500)),pos);}

function ejectCasing(){gun.updateWorldMatrix(true,true);const m=new THREE.Mesh(new THREE.CylinderGeometry(.026,.026,.13,6),new THREE.MeshStandardMaterial({color:0xd5a34a,metalness:.75,roughness:.3}));m.position.copy(weaponModels.rapid.localToWorld(new THREE.Vector3(.3,.1,.08)));m.userData.effect=true;scene.add(m);const velocity=new THREE.Vector3(3.5+Math.random()*2,2.5+Math.random()*2,Math.random()*2-1).applyQuaternion(camera.quaternion);particles.push({m,v:velocity,life:.85+Math.random()*.35,spin:new THREE.Vector3(8,12,5)});}
